// MF-14: valida el evento recibido de MediFlow y arma el texto de las alertas.
// El evento NO trae datos del paciente (ver app/services/alertas_n8n.py).
const evento = $input.first().json.body ?? {};

const valido =
  evento.urgente === true &&
  typeof evento.documento_id === 'string' &&
  evento.documento_id.length > 0;

if (!valido) {
  return [{ json: { valido: false, documento_id: evento.documento_id ?? null } }];
}

const limpiar = (v) => String(v ?? '—').replace(/[\r\n]+/g, ' ').trim() || '—';
// Slack interpreta &, < y > como marcado: se escapan los textos que vienen del modelo.
const slack = (v) => limpiar(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const estado = limpiar(evento.estado);
const titulos = {
  urgente: 'ALERTA URGENTE: caso urgente en cola de emergencia',
  revision_humana: 'ALERTA URGENTE: urgente, pendiente de revisión humana',
  error_tecnico: 'ALERTA URGENTE: urgente con fallo técnico, requiere atención manual',
};
const titulo = titulos[estado] ?? `ALERTA URGENTE: caso urgente (destino: ${estado})`;

const aviso = {
  revision_humana: 'Este caso NO fue validado automáticamente: un auditor debe revisarlo en el panel de revisión humana.',
  error_tecnico: 'El procesamiento terminó con un fallo técnico: revisar el caso manualmente.',
}[estado] ?? null;

const senales = Array.isArray(evento.senales_gravedad) && evento.senales_gravedad.length
  ? evento.senales_gravedad.join('; ')
  : '—';

const lineas = [
  ['Documento', evento.documento_id],
  ['Destino', estado],
  ['Tipo de documento', evento.tipo_documento],
  ['Especialidad', evento.especialidad],
  ['Nivel de urgencia', evento.nivel_urgencia],
  ['Confianza', evento.categoria_confianza],
  ['Señales de gravedad', senales],
  ['Registrado', evento.timestamp],
];

const texto = [titulo, '', ...lineas.map(([k, v]) => `${k}: ${limpiar(v)}`), ...(aviso ? ['', aviso] : [])].join('\n');
const slack_texto = [
  `:rotating_light: *${slack(titulo)}*`,
  ...lineas.map(([k, v]) => `• ${k}: ${k === 'Documento' ? '`' + slack(v) + '`' : slack(v)}`),
  ...(aviso ? ['', `_${slack(aviso)}_`] : []),
].join('\n');
const asunto = `[MediFlow] ${titulo} - ${limpiar(evento.documento_id)}`;

return [{ json: { valido: true, documento_id: evento.documento_id, estado, asunto, texto, slack_texto } }];
